const icons={today:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4m8-4v4M4 10h16"/>',plan:'<path d="M8 6h12M8 12h9M8 18h12M3 6h1M3 12h1M3 18h1"/>',growth:'<path d="M12 21V11m0 5C3 16 3 7 3 7s9-1 9 9zm0-5c0-8 9-8 9-8s0 8-9 8z"/>',inspiration:'<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.4"/><path d="m4 18 5-5 4 3 4-6 4 6"/>',talk:'<path d="M20 16a8 8 0 1 0-14 2l-2 4 6-2a8 8 0 0 0 10-4z"/>',home:'<path d="m3 11 9-8 9 8v10h-7v-7h-4v7H3z"/>',heart:'<path d="M20.5 8.5c0 5-8.5 11.5-8.5 11.5S3.5 13.5 3.5 8.5a4.5 4.5 0 0 1 8.5-2 4.5 4.5 0 0 1 8.5 2z"/>',profile:'<circle cx="12" cy="7" r="3"/><path d="M4 21c0-5 3-8 8-8s8 3 8 8z"/>',food:'<path d="M3.5 12h17c-.5 4.7-3.8 7.8-8.5 7.8S4 16.7 3.5 12Z"/><path d="M5 9.5h14M8 5.5c-1 1.5.8 2 0 3M12 3.8c-1 1.8 1 2.2 0 4.2M16 5.5c-1 1.5.8 2 0 3"/>',motivate:'<path d="M9 4c-4 4-5 9-1 14m7-14c4 4 5 9 1 14M8 18l4 3 4-3M8 11h8"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3z"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>'};
const icon=k=>`<svg class="inline-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.plan}</svg>`;
const seed=()=>({version:1,entered:false,profile:{name:'',story:'',goal:'',style:'gentle',memory:'',useMemory:false,dopamine:false},directions:[{id:'english',name:'Английский',why:'',archived:false},{id:'body',name:'Йога и тело',why:'',archived:false},{id:'music',name:'Пианино',why:'',archived:false},{id:'work',name:'Работа',why:'',archived:false}],tasks:[{id:uid(),title:'Немного английского',direction:'english',bucket:'soon',date:today(),done:false},{id:uid(),title:'Расстелить коврик и потянуться',direction:'body',bucket:'soon',date:today(),done:false},{id:uid(),title:'Поиграть любимую мелодию',direction:'music',bucket:'soon',date:null,done:false}],habits:[{id:uid(),title:'Английский',direction:'english',target:3,dates:[]},{id:uid(),title:'Йога',direction:'body',target:2,dates:[]}],inspiration:[],messages:[],meals:[],ideas:[],milestones:[]});
let data;let storageError=false;try{data=JSON.parse(localStorage.getItem(KEY))||seed();if(data.version!==1)throw Error('version')}catch{data=seed();storageError=true}
let selectedFieldId=null;let welcomeVisible=true;let page='today',planFilter='all',weekOffset=0,flowerIndex=Math.max(0,Math.min(5,Number(data.profile.theme)||0)),motivation='',selectedDirection='english';
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{toast('Не удалось сохранить. Освободите место или скачайте копию в настройках.');return false}}
let toastTimer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
const activeDirs=()=>data.directions.filter(d=>!d.archived);
const dirName=id=>data.directions.find(d=>d.id===id)?.name||'Личное';
const options=(selected,empty=true)=>`${empty?'<option value="">Без направления</option>':''}${data.directions.filter(d=>!d.archived||d.id===selected).map(d=>`<option value="${esc(d.id)}" ${d.id===selected?'selected':''}>${esc(d.name)}${d.archived?' · архив':''}</option>`).join('')}`;
const formatDate=d=>new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(d);
function weekDates(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)+weekOffset*7);return Array.from({length:7},(_,i)=>{const n=new Date(d);n.setDate(n.getDate()+i);return n})}
function flower(index=flowerIndex){
 const palettes=[['#343630','#93958b','#f8f4ef'],['#f20b11','#ed4cc8','#fff7ed'],['#4d83ed','#f0b940','#fff8ef'],['#f27333','#af62bd','#fff8eb'],['#dd4f89','#f4ad35','#fff8ef'],['#7a71e7','#ec6b4a','#fff8ef']];
 const [petal,ring,center]=palettes[index%palettes.length];
 const petals=Array.from({length:8},(_,i)=>`<g transform="rotate(${i*45+((i%3)-1)*3} 120 126)"><path d="M120 119 C103 91 104 49 116 31 C123 22 137 34 139 54 C143 79 131 105 120 119Z" fill="${petal}" stroke="${petal}" stroke-width="2" stroke-linejoin="round"/><path d="M119 106 C113 81 114 53 119 37 M124 108 C127 79 128 52 125 35 M118 99 C109 77 110 55 114 44" fill="none" stroke="${center}" stroke-width="1.7" opacity=".9" stroke-linecap="round"/></g>`).join('');
 return `<svg viewBox="0 0 240 250" role="img" aria-label="Нарисованный цветок с восемью лепестками">${petals}<circle cx="120" cy="126" r="27" fill="${ring}"/><path d="M110 115 Q121 106 132 117 Q140 127 132 139 Q119 148 110 138 Q103 127 110 115Z" fill="${center}"/></svg>`
}
const STYLE_PREVIEWS={gentle:'Давай без спешки. Что сейчас помогло бы тебе?',friend:'Я рядом. Расскажи, что навалилось — разберём вместе.',playful:'Так, кажется, у нас сюжет с препятствием. С чего начнём?',cheeky:'Ну всё, драму на паузу. Выберем один маленький ход?',direct:'Назови одну задачу. Найдём первый выполнимый шаг.'};
const navItems=[['today','Сегодня'],['plan','Гибкий план'],['growth','Развитие'],['inspiration','Вдохновение'],['talk','А давай поговорим'],['motivate','Уговори меня'],['food','Еда'],['field','Моё поле'],['someday','Когда-нибудь'],['journey','Мой путь']];
function nav(){return `<nav class="nav" aria-label="Разделы">${navItems.map(([key,label],i)=>`<button data-page="${key}" class="${page===key?'active ':''}${i===4?'spaced ':''}${i>3?'long':''}" ${page===key?'aria-current="page"':''}>${icon(key)}${label}</button>`).join('')}</nav>`}
function welcome(){return `<main class="welcome theme-${flowerIndex}"><div class="brand">${star()}тише.</div><button class="flower-button" data-action="flower" aria-label="Поменять цветок">${flower()}</button><h1>Твоя жизнь.<br>Твой темп.</h1><p>Место для того, что хочется растить.<br>Здесь можно быть собой.</p><button class="outline welcome-enter" data-action="enter">Зайти и выдохнуть</button><span class="tiny muted">${['Графитный классический','Красный и розовый','Голубой и золотой','Морковный и сиреневый','Розовый и янтарный','Лавандовый и коралловый'][flowerIndex]} · нажми на цветок, чтобы сменить</span><p class="tiny muted">Первая версия · данные хранятся в этом браузере.<br>Начальные дела — примеры, их можно изменить.</p><div class="whisper">расцветать можно без дедлайна.</div></main>`}
function whisper(section){const lines={today:['маленькое тоже считается.','не обязательно всё сразу.'],plan:['всему своё время.','движение важнее идеала.'],field:['тише. ты уже растёшь.','не торопи то, что растёт.'],someday:['всему своё время.','можно по-своему.'],journey:['ты уже в пути.','всё это уже с тобой.'],growth:['ты растёшь.'],inspiration:['а вдруг всё получится?'],talk:['здесь не нужно подбирать правильные слова.'],motivate:['пять минут побудем великими.'],settings:['можно по-своему.'],food:['еда — это забота, а не экзамен.']};const choices=lines[section]||lines.today;return choices[new Date().getDate()%choices.length]}
function render(){if(welcomeVisible){$('#app').innerHTML=welcome();return}const date=new Intl.DateTimeFormat('ru',{day:'numeric',month:'long',weekday:'long'}).format(new Date());$('#app').innerHTML=`<div class="shell theme-${flowerIndex} ${data.profile.dopamine?'dopamine':''}"><aside class="sidebar"><button class="brand" data-page="today">${star()}тише.</button><p class="brand-note">пространство для себя</p>${nav()}<div class="sidebar-bottom"><button class="profile" data-page="settings"><span class="avatar">${esc(data.profile.name?.slice(0,1).toUpperCase()||'я')}</span><span>${esc(data.profile.name||'Моё пространство')}</span>${icon('settings')}</button><span class="tiny muted">На этом устройстве <span class="version-tag">v0.1</span></span></div></aside><main class="main"><div class="mobile-header"><button class="brand" data-page="today">${star()}тише.</button><button data-action="menu" aria-label="Открыть меню">${icon('menu')}</button></div><div class="topline"><span>${esc(date)}</span><span class="topline-right"><i class="status-dot"></i> без спешки и по часам не нужно</span></div><div class="page">${pages[page]()}</div><footer class="footer"><span class="whisper ${['growth','talk','settings'].includes(page)?'blue':''}">${whisper(page)}</span><span class="footer-number">${String(Object.keys(pages).indexOf(page)+1).padStart(2,'0')} / 11</span></footer></main><nav class="mobile-nav" aria-label="Основная навигация">${[['today','Главная','home'],['plan','Неделя','today'],['field','Моё поле','growth'],['inspiration','Вдохновение — путеводная звезда','heart'],['talk','Поговорим','talk'],['settings','Настройки','profile'],['food','Еда','food']].map(([key,label,glyph])=>`<button data-page="${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''} aria-label="${label}">${key==='field'?'<span class="po-le">по-<br>ле</span>':key==='inspiration'?star(true).replace('class="star star-color"','class="star star-color guide-star"'):icon(glyph)}</button>`).join('')}</nav></div>`}
function heading(eyebrow,title,subtitle){return `<header class="heading"><div class="eyebrow">${eyebrow}</div><h1 class="${page==='today'?'':'page-title'}">${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</header>`}
function taskList(tasks){return `<ul class="tasks">${tasks.map(t=>`<li class="task ${t.done?'done':''}"><button class="check-star" data-action="toggleTask" data-id="${t.id}" aria-label="${t.done?'Вернуть в дела':'Отметить выполненным'}: ${esc(t.title)}" aria-pressed="${t.done}">${star()}</button><div class="task-body"><button class="task-name" data-action="editTask" data-id="${t.id}">${esc(t.title)}</button><div class="task-meta"><span>${esc(dirName(t.direction))}</span>${t.date===today()?'<span>· сегодня</span>':''}</div></div>${t.date!==today()&&!t.done?`<button class="task-action" data-action="toToday" data-id="${t.id}" aria-label="Добавить на сегодня: ${esc(t.title)}">на сегодня </button>`:`<button class="task-action" data-action="editTask" data-id="${t.id}" aria-label="Изменить: ${esc(t.title)}">···</button>`}</li>`).join('')}</ul>`}
function mobileToday(tasks){const focus=tasks[0],rituals=tasks.slice(1);const date=new Intl.DateTimeFormat('ru',{weekday:'short',day:'numeric',month:'long'}).format(new Date());return `<section class="original-today"><div class="original-top"><span>${star()}</span><button data-action="newTask" data-scope="today" aria-label="Добавить дело">+</button></div><h1>Сегодня</h1><p class="original-date">${esc(date)}</p><div class="original-divider"></div><h2>Фокус дня</h2>${focus?`<div class="original-task"><button class="original-check ${focus.done?'selected':''}" data-action="toggleTask" data-id="${focus.id}" aria-label="Отметить ${esc(focus.title)}">${focus.done?star():''}</button><button data-action="editTask" data-id="${focus.id}">${esc(focus.title)}</button></div>`:'<button class="text-button" data-action="newTask" data-scope="today">+ Выбрать один фокус</button>'}<div class="original-divider"></div><h2>Ритуалы</h2>${rituals.length?rituals.map(t=>`<div class="original-task"><button class="original-check ${t.done?'selected':''}" data-action="toggleTask" data-id="${t.id}" aria-label="Отметить ${esc(t.title)}">${t.done?star():''}</button><button data-action="editTask" data-id="${t.id}">${esc(t.title)}</button></div>`).join(''):'<p class="empty">Пока ничего не запланировано.</p>'}<button class="text-button original-add" data-action="newTask" data-scope="today">+ Добавить ритуал</button><button class="text-button" data-page="food">Записать еду</button><button class="text-button" data-page="field">Моё поле</button></section>`}
function todayPage(){const tasks=data.tasks.filter(t=>t.date===today());const done=tasks.filter(t=>t.done).length;const later=data.tasks.filter(t=>!t.done&&t.date!==today()).slice(0,2);const week=weekDates().map(iso);const count=data.habits.reduce((n,h)=>n+h.dates.filter(d=>week.includes(d)).length,0);const target=data.habits.reduce((n,h)=>n+h.target,0);return `${mobileToday(tasks)}${heading('Сегодня · твой свободный ритм','Можно в своём темпе.',`${data.profile.name?esc(data.profile.name)+', ':''}выбери то, чему хочется дать место сегодня.`)}<div class="two-col"><section><div class="section-head"><h2>На сегодня <span>${done} из ${tasks.length}</span></h2><button class="text-button" data-action="newTask" data-scope="today">+ добавить</button></div>${tasks.length?taskList(tasks):'<div class="empty">Сегодня пока чистый лист.<br>Оставь его таким или добавь один маленький шаг.</div>'}<button class="add-inline" data-action="newTask" data-scope="today"><span class="plus">+</span>Ещё один маленький шаг</button><section class="below"><div class="section-head"><h2>Когда захочется</h2><button class="text-button" data-page="plan">весь план </button></div>${later.length?taskList(later):'<p class="empty">Здесь будет то, что может подождать.</p>'}</section><button class="gentle-call" data-page="motivate">${icon('talk')}<span>Не хочется начинать?<br><span style="color:var(--ink)">Давай найдём маленький повод </span></span></button></section><aside class="quiet-aside"><div class="focus-symbol">${star()}</div><div class="eyebrow">Маленький фокус</div><p class="focus-title">Не всё сразу.<br>Что-то одно — уже хорошо.</p><p class="focus-copy">Тебе не нужно заполнять весь день. Здесь есть место и для пауз.</p><div class="rule"></div><div class="section-head"><h3>На этой неделе</h3><button class="text-button" data-page="growth" aria-label="Перейти к привычкам"></button></div>${data.habits.slice(0,3).map(h=>{const n=h.dates.filter(d=>week.includes(d)).length;return `<div class="week-brief"><span>${esc(h.title)}</span><span class="muted">${n} / ${h.target}</span></div><div class="little-bars" aria-label="${esc(h.title)}: ${n} из ${h.target}">${Array.from({length:h.target},(_,i)=>`<span class="${i<n?'filled':''}"></span>`).join('')}</div>`}).join('')}<p class="tiny muted" style="margin-top:22px">${count?'Каждый шаг остаётся с тобой.':'Начать можно с любого дня.'}</p></aside></div>`}
function planPage(){const tasks=data.tasks.filter(t=>planFilter==='all'||t.direction===planFilter);return `${mobileWeek()}<div class="original-plan-desktop">${heading('План без клеточек','Место для твоих планов.','Без расписания по часам. Можно переносить, передумывать и начинать заново.')}<div class="section-head"><div class="tabs" style="margin:0"><button class="tab ${planFilter==='all'?'selected':''}" data-action="filter" data-id="all">Всё</button>${activeDirs().map(d=>`<button class="tab ${planFilter===d.id?'selected':''}" data-action="filter" data-id="${d.id}">${esc(d.name)}</button>`).join('')}</div><button class="outline" data-action="newTask">+ Дело</button></div>${[['soon','В ближайшее время'],['someday','Когда-нибудь']].map(([bucket,label])=>`<section class="plan-section"><div class="section-head"><h2>${label}</h2></div>${tasks.some(t=>t.bucket===bucket&&!t.done)?taskList(tasks.filter(t=>t.bucket===bucket&&!t.done)):'<p class="empty">Здесь пока свободно.</p>'}</section>`).join('')}<details class="plan-section"><summary class="text-button">Завершённое · ${tasks.filter(t=>t.done).length}</summary>${taskList(tasks.filter(t=>t.done))}</details><div class="section-head"><h2>Мои направления</h2><button class="text-button" data-action="newDirection">+ новое направление</button></div><div class="directions">${activeDirs().map((d,i)=>`<article class="direction"><div class="direction-top"><h3>${esc(d.name)}</h3><div class="row"><button class="text-button" data-action="moveDirection" data-id="${d.id}" ${i===0?'disabled':''} aria-label="Поднять ${esc(d.name)}"></button><button class="text-button" data-action="editDirection" data-id="${d.id}">изменить</button></div></div><p>${esc(d.why||'Зачем мне это? Можно найти свой ответ в настройках направления.')}</p></article>`).join('')}</div>${data.directions.some(d=>d.archived)?`<details><summary class="text-button">Архив направлений</summary>${data.directions.filter(d=>d.archived).map(d=>`<div class="archive-row">${esc(d.name)}<button class="text-button" data-action="restoreDirection" data-id="${d.id}">вернуть</button></div>`).join('')}</details>`:''}</div>`}
function mobileWeek(){const days=weekDates(),slot=days.slice(0,5);return `<section class="original-week"><div class="original-week-arrows"><button data-action="prevWeek" aria-label="Предыдущая неделя">Назад</button><button data-action="nextWeek" ${weekOffset===0?'disabled':''} aria-label="Следующая неделя">Далее</button></div><h1>Неделя</h1><p>${formatDate(days[0])} — ${formatDate(days[6])}</p><div class="original-divider"></div>${data.habits.map(h=>`<div class="original-week-row"><button class="original-week-name" data-action="editHabit" data-id="${h.id}">${esc(h.title)}</button><div class="original-week-marks">${slot.map(d=>`<button class="${h.dates.includes(iso(d))?'marked':''}" data-action="habitDay" data-id="${h.id}" data-date="${iso(d)}" ${iso(d)>today()?'disabled':''} aria-label="${esc(h.title)}, ${formatDate(d)}">${h.dates.includes(iso(d))?star():'<span></span>'}</button>`).join('')}</div></div>`).join('')}<button class="text-button" data-action="newHabit">+ Добавить привычку</button><button class="text-button" data-page="growth">Моё поле</button><button class="text-button" data-action="showFlexiblePlan">Все дела </button></section>`}
function growthPage(){const days=weekDates(),labels=['пн','вт','ср','чт','пт','сб','вс'];return `${mobileGrowth()}<div class="original-growth-desktop">${heading('Развитие','Понемногу — к своему.','Недельные ориентиры вместо идеальных серий. Пропуск ничего не обнуляет.')}<div class="section-head"><div class="week-switch"><button data-action="prevWeek" aria-label="Предыдущая неделя">Назад</button><span>${formatDate(days[0])} — ${formatDate(days[6])}</span><button data-action="nextWeek" ${weekOffset===0?'disabled':''} aria-label="Следующая неделя">Далее</button></div><button class="outline" data-action="newHabit">+ Привычка</button></div>${data.habits.length?data.habits.map(h=>{const n=h.dates.filter(d=>days.map(iso).includes(d)).length;return `<article class="habit"><div class="habit-top"><div><h3>${esc(h.title)}</h3><p>${n} из ${h.target} за неделю · ${esc(dirName(h.direction))}</p></div><button class="text-button" data-action="editHabit" data-id="${h.id}">изменить</button></div><div class="week-days">${days.map((d,i)=>`<button class="day-button ${h.dates.includes(iso(d))?'checked':''} ${iso(d)===today()?'today':''}" data-action="habitDay" data-id="${h.id}" data-date="${iso(d)}" ${iso(d)>today()?'disabled':''} aria-pressed="${h.dates.includes(iso(d))}" aria-label="${esc(h.title)}, ${formatDate(d)}"><span>${labels[i]} · ${d.getDate()}</span>${star()}</button>`).join('')}</div></article>`}).join(''):'<p class="empty">Добавь то, к чему хочется возвращаться.</p>'}<p class="tiny muted" style="margin-top:27px">Звёздочка — знак внимания к себе. Не оценка.</p></div>`}
function mobileGrowth(){return `<section class="original-growth"><div class="original-back"><button data-page="plan">Назад</button><span class="growth-star">${star()}</span></div><h1>Развитие</h1>${activeDirs().map(d=>`<button class="original-direction" data-action="editDirection" data-id="${d.id}"><span>${esc(d.name)}</span><span></span></button>`).join('')}<button class="text-button" data-action="newDirection">+ Направление</button></section>`}
function inspirationPage(){return `${heading('Вдохновение','Вдохновение','Собирай здесь ощущения, места и маленькие напоминания о своей жизни.')}<div class="inspiration-intro"><span class="tiny muted">Твоя личная коллекция · ${data.inspiration.length}</span><div class="row"><button class="text-button" data-action="newNote">+ мысль</button><label class="outline photo-label">+ Фотография<input type="file" id="photoInput" accept="image/jpeg,image/png,image/webp"></label></div></div><div class="mood-grid">${data.inspiration.length?data.inspiration.map((item,i)=>item.type==='photo'?`<figure class="mood"><img src="${esc(item.src)}" alt="${esc(item.caption||'Мой источник вдохновения')}"><figcaption><span>${esc(item.caption)}</span><button data-action="deleteInspiration" data-id="${item.id}" aria-label="Удалить фотографию">×</button></figcaption>${i%4===0?`<span class="photo-star">${star(true)}</span>`:''}</figure>`:`<article class="note-card"><p>${esc(item.text)}</p><small>сохранить это чувство <button data-action="deleteInspiration" data-id="${item.id}" aria-label="Удалить мысль">×</button></small></article>`).join(''):`<div class="mood-empty">${star(true)}<h2>Здесь будут твои «хочу».</h2><p class="muted" style="font-size:12px;margin-top:13px">Фото из прошлого чата недоступны.<br>Добавь свой снимок или мысль — без рамок и лишнего шума.</p></div>`}</div>`}
function talkPage(){return `<section class="conversation">${heading('Место для разговора','А давай поговорим.','Можно с середины. Можно просто «я устала».')}<p class="notice">Сообщение и последние реплики отправляются ИИ после нажатия «Отправить». Разговор хранится в этом браузере. Память передаётся только с твоего разрешения.</p><div class="messages">${data.messages.length?data.messages.map(m=>`<div class="message ${m.role}"><div class="message-label">${m.role==='user'?'ты':'тише.'}</div>${esc(m.text)}</div>`).join(''):`<div class="message assistant">Что сейчас занимает больше всего места в твоей голове?</div>`}</div><form id="talkForm"><div class="composer"><textarea name="message" placeholder="С чего хочется начать?.." aria-label="Твоя мысль" required maxlength="4000"></textarea><button type="submit" aria-label="Отправить мысль">Отправить</button></div></form><div class="suggestions"><button data-action="talkPrompt" data-id="Я устала и ничего не хочу">Я устала</button><button data-action="talkPrompt" data-id="Мне сложно начать">Сложно начать</button><button data-action="talkPrompt" data-id="Хочу разобраться, чего я хочу">Чего я хочу?</button></div>${data.messages.length?'<button class="text-button" data-action="clearChat">Очистить записи разговора</button>':''}<p class="tiny muted">Разговоры не попадают в постоянную память автоматически. Её содержание ты задаёшь в настройках.</p></section>`}
function motivatePage(){return `<section class="conversation">${heading('Немного поддержки','Я не хочу этим заниматься.<br>Уговори меня.','Без чувства вины. И с правом сегодня отдохнуть.')}<p class="notice">ИИ опирается на твой стиль поддержки, цели и причину «зачем». Если связь недоступна, останется бережный локальный ответ.</p><form id="motivateForm"><label>К чему сложно подступиться?<select name="direction" required>${options(selectedDirection,false)}</select></label><label>Что сейчас больше похоже на тебя?<select name="feeling"><option value="start">Сложно сделать первый шаг</option><option value="overwhelmed">Всё кажется слишком большим</option><option value="tired">Я правда устала</option></select></label><button class="outline" type="submit" ${!activeDirs().length?'disabled':''}>Найти маленький повод </button></form>${motivation?`<div class="motivation-result" role="status">${esc(motivation)}</div><div class="row wrap"><button class="outline" data-action="tinyStep">Добавить маленький шаг на сегодня</button><button class="text-button" data-action="rest">Сегодня выбираю отдых</button></div>`:''}<button class="text-button" style="margin-top:24px" data-page="settings">Рассказать, зачем мне это </button></section>`}
function settingsPage(){return `${heading('Моё пространство','По-твоему.','То, что помогает помнить, ради чего всё это.')}<form id="settingsForm" class="settings"><section class="settings-section"><h2>Обо мне</h2><label>Как к тебе обращаться<input name="name" maxlength="50" value="${esc(data.profile.name)}" placeholder="Твоё имя"></label><label>Какую жизнь я хочу построить<textarea name="story" maxlength="4000" placeholder="Что для тебя важно?">${esc(data.profile.story)}</textarea></label><label>Мои личные цели<textarea name="goal" maxlength="4000" placeholder="К чему хочется прийти, без обязательных сроков">${esc(data.profile.goal)}</textarea></label></section><section class="settings-section"><h2>Зачем мне это</h2><p>У каждого направления может быть свой очень личный смысл.</p>${activeDirs().map(d=>`<label>${esc(d.name)}<textarea name="why_${d.id}" maxlength="2000" placeholder="Не «надо», а ради чего?">${esc(d.why)}</textarea></label>`).join('')}</section><section class="settings-section"><h2>Как меня поддерживать</h2><label>Стиль поддержки<select name="style" id="styleSelect">${[['gentle','Бережно'],['friend','По-дружески'],['playful','Игриво'],['cheeky','Дерзко, но тепло'],['direct','Прямо и ясно']].map(([v,l])=>`<option value="${v}" ${data.profile.style===v?'selected':''}>${l}</option>`).join('')}</select></label><p class="style-preview" id="stylePreview">${esc(STYLE_PREVIEWS[data.profile.style]||STYLE_PREVIEWS.gentle)}</p><label>Персональная память<textarea name="memory" maxlength="4000" placeholder="Что важно помнить обо мне? Только то, что ты хочешь сохранить.">${esc(data.profile.memory)}</textarea></label><label class="check-label"><input type="checkbox" name="useMemory" ${data.profile.useMemory?'checked':''}><span>Использовать эти заметки в ответах ИИ. Без этой отметки персональная память не отправляется.</span></label><p>Можно изменить или стереть память в этом поле. История разговоров сюда не добавляется.</p></section><section class="settings-section"><h2>Внешний вид</h2><label class="check-label"><input type="checkbox" name="dopamine" ${data.profile.dopamine?'checked':''}><span>Дофаминовое приложение — мягкие цветные акценты на разделах, кнопках и отметках.</span></label><p>Можно включить и выключить в любой момент.</p></section><section class="settings-section"><h2>Данные и доступ</h2><p>Сейчас это локальная первая версия: один набор данных в этом браузере, без отдельных аккаунтов и синхронизации. На общем устройстве записи видны другим людям с доступом к этому браузеру. Не используй её как защищённое хранилище.</p><p>Многопользовательская архитектура подготовлена отдельно. Доступ к ИИ на сервере требует входа через Sites. Записи и фотографии пока остаются только в этом браузере; синхронизации между устройствами нет.</p><div class="row wrap"><button type="button" class="outline" data-action="export">Скачать мои данные</button><button type="button" class="text-button danger" data-action="reset">Удалить все мои данные</button></div></section><div class="settings-actions"><button class="outline solid" type="submit">Сохранить настройки</button><span class="draft-status" id="settingsStatus">Изменения сохраняются по кнопке</span></div></form>`}
function fieldActivity(d){return data.tasks.filter(t=>t.direction===d.id&&t.done).length+data.habits.filter(h=>h.direction===d.id).reduce((n,h)=>n+h.dates.length,0)}
function fieldStage(n){return n>=3?'flower':n>=1?'colored':'star'}
function fieldPage(){const dirs=activeDirs();return `<section class="new-section field-page"><div class="new-section-top">${star()}<button data-action="newDirection" aria-label="Добавить направление">+</button></div><h1>Моё поле</h1><p class="new-subtitle">Что ты растишь в своей жизни</p><div class="field-composition">${dirs.map((d,i)=>{const n=fieldActivity(d),stage=fieldStage(n);return `<button class="field-plant ${stage}" data-action="viewField" data-id="${d.id}" aria-label="${esc(d.name)}, ${n} занятий"><span class="field-icon" style="--plant-color:${['#d9684b','#558db6','#c88a9d','#899b68','#b18fc5'][i%5]}">${stage==='flower'?flower(i+1):star(stage==='colored')}</span><span>${esc(d.name)}</span></button>`}).join('')}</div>${dirs.length?'':'<p class="empty">Здесь ждёт место для первого направления.</p>'}<button class="text-button" data-action="newDirection">+ Новое направление</button><div class="field-links"><button data-page="someday">Когда-нибудь</button><button data-page="journey">Мой путь</button></div>${selectedFieldId?fieldDetail(selectedFieldId):''}<p class="tiny muted" style="margin-top:30px">Занятия добавляют цвет. Пропуски ничего не забирают.</p></section>`}
function fieldDetail(id){const d=data.directions.find(x=>x.id===id);if(!d)return '';const tasks=data.tasks.filter(t=>t.direction===id&&t.done),habits=data.habits.filter(h=>h.direction===id),n=fieldActivity(d);return `<div class="field-detail"><div class="section-head"><h2>${esc(d.name)}</h2><button class="text-button" data-action="closeField">Закрыть</button></div><p>${esc(d.why||'Зачем тебе это? Свой ответ можно добавить в настройках направления.')}</p><p class="tiny muted">${n} ${n%10===1&&n%100!==11?'отмеченное занятие':[2,3,4].includes(n%10)&&![12,13,14].includes(n%100)?'отмеченных занятия':'отмеченных занятий'} · ${fieldStage(n)==='flower'?'цветок уже появился':n?'звёздочка становится цветной':'всё начинается с интереса'}</p>${tasks.length?`<h3>Что уже сделано</h3>${tasks.slice(-5).map(t=>`<div class="field-history">${star()}<span>${esc(t.title)}</span></div>`).join('')}`:''}${habits.length?`<p class="tiny muted">Привычки: ${habits.map(h=>esc(h.title)).join(', ')}</p>`:''}<button class="text-button" data-action="editDirection" data-id="${id}">Изменить направление</button></div>`}
function somedayPage(){const ideas=data.ideas||[];return `<section class="new-section"><div class="new-section-top">${star()}<button data-action="newIdea" aria-label="Добавить идею">+</button></div><h1>Когда-нибудь</h1><p class="new-subtitle">Интересы без сроков и обязательств</p>${ideas.length?ideas.map(x=>`<article class="idea-row"><button data-action="editIdea" data-id="${x.id}"><strong>${esc(x.title)}</strong>${x.description?`<span>${esc(x.description)}</span>`:''}${x.why?`<small>Почему интересно: ${esc(x.why)}</small>`:''}</button><button class="text-button" data-action="promoteIdea" data-id="${x.id}">В моё поле</button></article>`).join(''):'<p class="empty">Можно просто оставить здесь мысль. Решать сейчас не нужно.</p>'}<button class="text-button" data-action="newIdea">+ Добавить идею</button><button class="text-button" data-page="field">Моё поле</button></section>`}
function journeyPage(){const milestones=data.milestones||[],archived=data.directions.filter(d=>d.archived),completed=data.tasks.filter(t=>t.done);return `<section class="new-section"><div class="new-section-top">${star()}<button data-action="newMilestone" aria-label="Добавить важный этап">+</button></div><h1>Мой путь</h1><p class="new-subtitle">То, что уже стало частью твоей истории</p><div class="journey-timeline">${milestones.map(m=>`<article class="journey-row">${star()}<div><strong>${esc(m.title)}</strong>${m.note?`<p>${esc(m.note)}</p>`:''}<small>${esc(m.date)}</small></div><button class="text-button" data-action="deleteMilestone" data-id="${m.id}">Удалить</button></article>`).join('')}${archived.map(d=>`<article class="journey-row">${star()}<div><strong>${esc(d.name)}</strong><p>${esc(d.why||'Направление сохранено в твоей истории.')}</p></div><button class="text-button" data-action="restoreDirection" data-id="${d.id}">Вернуть в поле</button></article>`).join('')}${completed.slice(-12).map(t=>`<article class="journey-row">${star()}<div><strong>${esc(t.title)}</strong><small>${esc(dirName(t.direction))}</small></div></article>`).join('')}</div>${!milestones.length&&!archived.length&&!completed.length?'<p class="empty">Здесь появятся твои шаги и важные открытия.</p>':''}<button class="text-button" data-action="newMilestone">+ Запомнить важный этап</button><p class="tiny muted">Это история опыта, а не список пропусков.</p></section>`}
function ideaDialog(id){const item=(data.ideas||[]).find(x=>x.id===id);openDialog(item?'Идея':'Когда-нибудь',`<label>Название<input name="title" required maxlength="100" value="${esc(item?.title||'')}" autofocus></label><label>Описание<textarea name="description" maxlength="1000">${esc(item?.description||'')}</textarea></label><label>Почему мне это интересно?<textarea name="why" maxlength="1000">${esc(item?.why||'')}</textarea></label><div class="dialog-actions">${item?`<button type="button" class="text-button danger" data-action="deleteIdea" data-id="${id}">Удалить</button>`:'<span></span>'}<button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const title=f.get('title').trim();if(!title)return;data.ideas??=[];const update={title,description:f.get('description').trim(),why:f.get('why').trim()};if(item)Object.assign(item,update);else data.ideas.push({id:uid(),...update});save();closeDialog();render()})}
function milestoneDialog(){openDialog('Важный этап',`<label>Что хочется запомнить?<input name="title" required maxlength="120" autofocus></label><label>Несколько слов об этом<textarea name="note" maxlength="1000"></textarea></label><div class="dialog-actions"><span></span><button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const title=f.get('title').trim();if(!title)return;data.milestones??=[];data.milestones.push({id:uid(),title,note:f.get('note').trim(),date:today()});save();closeDialog();render()})}
const FOOD_GUIDE=[
 {names:/яйц|омлет/i, label:'яйцо',kcal:75,protein:true},
 {names:/куриц|индейк/i,label:'порция птицы',kcal:180,protein:true},
 {names:/рыб|лосос|тунец/i,label:'порция рыбы',kcal:200,protein:true},
 {names:/творог/i,label:'порция творога',kcal:170,protein:true},
 {names:/йогурт|кефир/i,label:'порция йогурта',kcal:110,protein:true},
 {names:/фасол|чечевиц|нут/i,label:'порция бобовых',kcal:180,protein:true},
 {names:/каша|овсян/i,label:'порция каши',kcal:180,grain:true},
 {names:/рис|гречк|макарон/i,label:'порция гарнира',kcal:200,grain:true},
 {names:/хлеб|тост/i,label:'кусок хлеба',kcal:90,grain:true},
 {names:/овощ|салат|помидор|огурец/i,label:'порция овощей',kcal:70,produce:true},
 {names:/фрукт|яблок|банан|ягод/i,label:'фрукт или ягоды',kcal:100,produce:true},
 {names:/орех/i,label:'горсть орехов',kcal:180,fat:true},
 {names:/масло/i,label:'порция масла',kcal:120,fat:true},
 {names:/сыр/i,label:'порция сыра',kcal:120,protein:true,fat:true}
];
function foodEstimate(text){const matched=FOOD_GUIDE.filter(x=>x.names.test(text));if(!matched.length)return {matched:[],range:null};const sum=matched.reduce((n,x)=>n+x.kcal,0);return {matched,range:[Math.round(sum*.65/10)*10,Math.round(sum*1.5/10)*10]}}
function foodAnalysis(meals){if(!meals.length)return 'Расскажи, что было на тарелке. Можно без граммов и без идеальной точности.';
 const recognized=meals.flatMap(m=>foodEstimate(m.text).matched),unknown=meals.filter(m=>!foodEstimate(m.text).matched.length).length;
 const total=meals.reduce((n,m)=>n+(foodEstimate(m.text).matched.reduce((v,x)=>v+x.kcal,0)),0);
 let lines=['Спасибо, что записала. Это помогает заметить, как ты заботишься о себе.'];
 if(total)lines.push(`По распознанным продуктам очень грубый ориентир — около ${Math.round(total*.65/10)*10}–${Math.round(total*1.5/10)*10} ккал. Порции и способ приготовления неизвестны, поэтому реальное значение может быть другим.`);
 if(unknown)lines.push(`${unknown===1?'Одну запись':'Некоторые записи'} я не смогла оценить по составу. Можно уточнить продукты и примерную порцию.`);
 if(recognized.some(x=>x.protein)&&recognized.some(x=>x.produce))lines.push('В записях есть и источник белка, и овощи или фрукты. Похоже на приятное разнообразие.');
 else if(!recognized.some(x=>x.protein))lines.push('В записанном пока не вижу явного источника белка. Если захочется, можно добавить яйца, рыбу, творог или бобовые. Это наблюдение по записям, не оценка всего твоего питания.');
 else if(!recognized.some(x=>x.produce))lines.push('Если захочется разнообразия, можно добавить фрукт или овощи.');
 lines.push('По одному дню нельзя сказать, «нормально» ли ты питаешься. Как ты сама чувствуешь себя после еды — сытость, энергия, комфорт?');return lines.join('\n\n')}
function foodPage(){const meals=(data.meals||[]).filter(m=>m.date===today());const saved=foodAnalysis(meals);return `${heading('Ежедневный помощник','Еда и самочувствие.','Записывай обычными словами. Без оценки, запретов и точного счёта.')}<section class="food-page"><div class="food-top"><span class="food-mark">${icon('food')}</span><h1>Еда</h1><p>${new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date())}</p></div><form id="foodForm"><label>Что ты ела сегодня?<textarea name="meal" required maxlength="500" placeholder="Например: омлет, хлеб и помидоры. Можно указать порцию своими словами."></textarea></label><button type="submit" class="outline">Записать</button></form><div class="food-list">${meals.map(m=>`<div class="food-entry"><span>${esc(m.text)}</span><button data-action="removeMeal" data-id="${m.id}" aria-label="Удалить запись о еде">Удалить</button></div>`).join('')}</div><button class="outline food-analyze" data-action="analyzeFood" ${!meals.length?'disabled':''}>Давай мягко посмотрим на день</button>${foodResult?`<div class="food-answer"><span class="eyebrow">Разговор о еде</span><p>${esc(foodResult)}</p></div>`:''}<p class="notice">Для разбора записи о еде отправляются ИИ. Оценка примерная и не определяет потребности организма. Можно совсем не считать калории — смысл раздела в бережном наблюдении.</p></section>`}
let foodResult='';
const pages={today:todayPage,plan:planPage,growth:growthPage,inspiration:inspirationPage,talk:talkPage,motivate:motivatePage,food:foodPage,field:fieldPage,someday:somedayPage,journey:journeyPage,settings:settingsPage};
function positionDialog(){const d=$('#dialog'),v=window.visualViewport;if(!d?.open||!v)return;d.style.top=`${v.offsetTop+v.height/2}px`;d.style.maxHeight=`${Math.max(180,v.height-24)}px`}
window.visualViewport?.addEventListener('resize',positionDialog);window.visualViewport?.addEventListener('scroll',positionDialog);
function openDialog(title,body,onSubmit){const d=$('#dialog');d.innerHTML=`<form class="dialog-body" id="modalForm"><div class="dialog-head"><h2>${title}</h2><button type="button" data-action="closeDialog" aria-label="Закрыть">×</button></div>${body}</form>`;d.showModal();positionDialog();$('#modalForm').onsubmit=e=>{e.preventDefault();onSubmit?.(new FormData(e.target));}}
function closeDialog(){$('#dialog').close()}
function confirmAction(title,copy,action){openDialog(title,`<p class="muted" style="font-size:13px">${copy}</p><div class="dialog-actions"><button type="button" class="outline" data-action="closeDialog">Отмена</button><button type="submit" class="outline danger">Удалить</button></div>`,()=>{action();closeDialog();save();render()})}
function taskDialog(id,scope){const t=data.tasks.find(t=>t.id===id);openDialog(t?'Твоё дело':'Один маленький шаг',`<label>Что хочется сделать<input name="title" required maxlength="200" value="${esc(t?.title||'')}" placeholder="Например, прочитать пару страниц" autofocus></label><label>Направление<select name="direction">${options(t?.direction||(planFilter==='all'?'':planFilter))}</select></label><label>Когда<select name="when">${[['today','Сегодня'],['soon','В ближайшее время'],['someday','Когда-нибудь']].map(([v,l])=>`<option value="${v}" ${v===(t?(t.date===today()?'today':t.bucket):(scope||'soon'))?'selected':''}>${l}</option>`).join('')}</select></label><div class="dialog-actions">${t?`<button type="button" class="text-button danger" data-action="deleteTask" data-id="${t.id}">Удалить</button>`:'<span></span>'}<button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const title=f.get('title').trim();if(!title)return;const when=f.get('when');const update={title,direction:f.get('direction'),bucket:when==='someday'?'someday':'soon',date:when==='today'?today():null};if(t)Object.assign(t,update);else data.tasks.push({id:uid(),done:false,...update});save();closeDialog();render();toast('Есть место для этого шага')})}
function directionDialog(id){const d=data.directions.find(d=>d.id===id);openDialog(d?'Настроить направление':'Новое направление',`<label>Название<input name="name" required maxlength="70" value="${esc(d?.name||'')}" autofocus placeholder="Например, фотография"></label><label>Зачем мне это<textarea name="why" maxlength="2000" placeholder="Что это привносит в мою жизнь?">${esc(d?.why||'')}</textarea></label><div class="dialog-actions">${d?`<button type="button" class="text-button" data-action="archiveDirection" data-id="${d.id}">В архив</button>`:'<span></span>'}<button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const name=f.get('name').trim();if(!name)return;if(d)Object.assign(d,{name,why:f.get('why').trim()});else data.directions.push({id:uid(),name,why:f.get('why').trim(),archived:false});save();closeDialog();render()})}
function habitDialog(id){const h=data.habits.find(h=>h.id===id);openDialog(h?'Твоя привычка':'Новая привычка',`<label>К чему возвращаться<input name="title" required maxlength="100" value="${esc(h?.title||'')}" autofocus></label><label>Направление<select name="direction">${options(h?.direction)}</select></label><label>Сколько раз за неделю<input type="number" name="target" min="1" max="7" required value="${h?.target||3}"></label><p class="tiny muted">Это ориентир, а не обязательство. Время дня выбираешь сама.</p><div class="dialog-actions">${h?`<button type="button" class="text-button danger" data-action="deleteHabit" data-id="${h.id}">Удалить</button>`:'<span></span>'}<button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const title=f.get('title').trim();if(!title)return;const update={title,direction:f.get('direction'),target:Math.min(7,Math.max(1,Number(f.get('target'))))};if(h)Object.assign(h,update);else data.habits.push({id:uid(),dates:[],...update});save();closeDialog();render()})}
function appendTalk(text){text=String(text||'').trim().slice(0,4000);if(!text)return;const questions=['Если убрать слово «надо», чего тебе сейчас хочется?','Что из этого зависит от тебя, а что можно пока отпустить?','Какой самый маленький добрый шаг ты могла бы предложить себе?'];const index=data.messages.filter(m=>m.role==='user').length%questions.length;let reply=/устал|нет сил|ничего не хочу/i.test(text)?'Можно остановиться. Что поддержало бы тебя сейчас: тишина, еда, сон или разговор с близким человеком?':/начать|сложно|страшно/i.test(text)?'Как выглядел бы первый шаг, настолько маленький, что его можно сделать без подготовки?':questions[index];if(data.profile.useMemory&&data.profile.memory)reply+=`\n\nТвоё напоминание себе: «${data.profile.memory.slice(0,300)}»`;data.messages.push({role:'user',text});save();render();const history=data.messages.slice(-8).map(m=>({role:m.role,text:m.text}));if(typeof fetch!=='function'){data.messages.push({role:'assistant',text:reply});save();render();return}aiRequest('talk',{text,history,profile:aiProfile()}).then(answer=>{data.messages.push({role:'assistant',text:answer});save();render()}).catch(()=>{data.messages.push({role:'assistant',text:reply});save();render();toast('ИИ сейчас недоступен. Показан локальный вопрос для размышления.')});setTimeout(()=>$('.composer textarea')?.focus(),0)}
function aiProfile(){return {name:data.profile.name,goal:data.profile.goal,style:data.profile.style,memory:data.profile.useMemory?data.profile.memory:''}}
async function aiRequest(mode,payload){const response=await fetch('/api/ai',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mode,...payload})});if(!response.ok)throw Error('AI unavailable');const body=await response.json();if(typeof body.text!=='string'||!body.text.trim())throw Error('Empty AI answer');return body.text.trim()}
function analyzeFoodWithAI(){const meals=(data.meals||[]).filter(m=>m.date===today()),local=foodAnalysis(meals);if(typeof fetch!=='function'){foodResult=local;render();return}foodResult='Смотрю на записи и собираю мягкий ориентир…';render();aiRequest('food',{text:meals.map(m=>m.text).join('\n'),profile:{style:data.profile.style}}).then(answer=>{foodResult=answer;render()}).catch(()=>{foodResult=local;render();toast('ИИ сейчас недоступен. Показан локальный ориентир.')})}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`tihiy-ritm-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Копия данных скачана')}
async function addPhoto(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Выбери JPEG, PNG или WebP');return}if(file.size>20*1024*1024){toast('Выбери фотографию меньше 20 МБ');return}try{const bmp=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(bmp.width,bmp.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bmp.width*scale);canvas.height=Math.round(bmp.height*scale);canvas.getContext('2d').drawImage(bmp,0,0,canvas.width,canvas.height);bmp.close();const src=canvas.toDataURL('image/jpeg',.78);openDialog('Сохранить ощущение',`<label>Подпись<input name="caption" maxlength="160" placeholder="О чём тебе напоминает этот снимок?"></label><p class="tiny muted">Фото сохранится только в этом браузере.</p><div class="dialog-actions"><button type="button" class="outline" data-action="closeDialog">Отмена</button><button type="submit" class="outline solid">Добавить</button></div>`,f=>{data.inspiration.push({id:uid(),type:'photo',src,caption:f.get('caption').trim()});if(!save()){data.inspiration.pop();return}closeDialog();render();toast('Вдохновение рядом')})}catch{toast('Не получилось открыть фотографию. Попробуй другой файл.')}}
let unsavedSettings=false;
document.addEventListener('input',e=>{if(e.target.closest('#settingsForm')){unsavedSettings=true;$('#settingsStatus').textContent='Есть несохранённые изменения'}});
function navigate(next){if(unsavedSettings&&page==='settings'){openDialog('Сохранить изменения?',`<p class="tiny muted">Ты изменила настройки. Сохрани их перед переходом или продолжи без сохранения.</p><div class="dialog-actions"><button type="button" class="text-button" id="discardSettings">Не сохранять</button><button type="submit" class="outline solid">Сохранить</button></div>`,()=>{if(!persistSettings(new FormData($('#settingsForm'))))return;closeDialog();page=next;render();window.scrollTo(0,0)});$('#discardSettings').onclick=()=>{unsavedSettings=false;closeDialog();page=next;render();window.scrollTo(0,0)};return}page=next;weekOffset=0;render();window.scrollTo(0,0)}
function persistSettings(f){for(const key of ['name','story','goal','style','memory'])data.profile[key]=f.get(key).trim();data.profile.useMemory=f.has('useMemory');data.profile.dopamine=f.has('dopamine');activeDirs().forEach(d=>d.why=f.get(`why_${d.id}`).trim());const ok=save();if(ok){unsavedSettings=false;toast('Сохранено. Это пространство становится твоим.')}return ok}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){closeDialog();navigate(b.dataset.page);return}const id=b.dataset.id,action=b.dataset.action;switch(action){case'enter':welcomeVisible=false;render();break;case'flower':flowerIndex=(flowerIndex+1)%6;data.profile.theme=flowerIndex;if(flowerIndex===0)data.profile.dopamine=false;save();render();break;case'menu':openDialog('Твоё пространство',`<div class="nav-modal">${nav()}<button class="text-button" data-page="settings">${icon('settings')} Настройки</button><button class="text-button" data-page="motivate">Уговори меня </button></div>`,()=>{});break;case'closeDialog':closeDialog();break;case'viewField':selectedFieldId=id;render();break;case'closeField':selectedFieldId=null;render();break;case'newIdea':ideaDialog();break;case'editIdea':ideaDialog(id);break;case'promoteIdea':{const idea=(data.ideas||[]).find(x=>x.id===id);if(idea){data.directions.push({id:uid(),name:idea.title,why:idea.why||idea.description,archived:false});data.ideas=data.ideas.filter(x=>x.id!==id);save();page='field';render();toast('Идея теперь в твоём поле')}break}case'deleteIdea':confirmAction('Удалить идею?','Идея исчезнет из списка «Когда-нибудь».',()=>data.ideas=data.ideas.filter(x=>x.id!==id));break;case'newMilestone':milestoneDialog();break;case'deleteMilestone':confirmAction('Удалить этап?','Эта запись исчезнет из истории.',()=>data.milestones=data.milestones.filter(x=>x.id!==id));break;case'newTask':taskDialog(null,b.dataset.scope);break;case'editTask':taskDialog(id);break;case'toggleTask':{const t=data.tasks.find(t=>t.id===id);t.done=!t.done;save();render();break}case'toToday':data.tasks.find(t=>t.id===id).date=today();save();render();toast('Добавлено на сегодня');break;case'deleteTask':data.tasks=data.tasks.filter(t=>t.id!==id);save();closeDialog();render();break;case'showFlexiblePlan':document.querySelector('#app').classList.add('show-flexible');break;case'filter':planFilter=id;render();document.querySelector('#app').classList.add('show-flexible');break;case'newDirection':directionDialog();break;case'editDirection':directionDialog(id);break;case'archiveDirection':data.directions.find(d=>d.id===id).archived=true;planFilter='all';save();closeDialog();render();toast('Направление в архиве. Дела сохранены.');break;case'restoreDirection':data.directions.find(d=>d.id===id).archived=false;save();render();break;case'moveDirection':{const i=data.directions.findIndex(d=>d.id===id);let p=i-1;while(p>=0&&data.directions[p].archived)p--;if(p>=0)[data.directions[i],data.directions[p]]=[data.directions[p],data.directions[i]];save();render();break}case'newHabit':habitDialog();break;case'editHabit':habitDialog(id);break;case'deleteHabit':confirmAction('Удалить привычку?','Её отметки за прошлые недели тоже будут удалены.',()=>data.habits=data.habits.filter(h=>h.id!==id));break;case'habitDay':{const h=data.habits.find(h=>h.id===id),date=b.dataset.date;if(date>today())return;h.dates=h.dates.includes(date)?h.dates.filter(d=>d!==date):[...h.dates,date];save();render();break}case'prevWeek':weekOffset--;render();break;case'nextWeek':weekOffset=Math.min(0,weekOffset+1);render();break;case'newNote':openDialog('Мысль, которую хочется оставить',`<label>Твои слова<textarea name="text" required maxlength="1000" autofocus placeholder="Мне хочется…"></textarea></label><div class="dialog-actions"><span></span><button class="outline solid" type="submit">Сохранить</button></div>`,f=>{const text=f.get('text').trim();if(!text)return;data.inspiration.push({id:uid(),type:'note',text});save();closeDialog();render()});break;case'deleteInspiration':confirmAction('Удалить из вдохновения?','Эта запись исчезнет из коллекции.',()=>data.inspiration=data.inspiration.filter(i=>i.id!==id));break;case'talkPrompt':appendTalk(id);break;case'clearChat':confirmAction('Очистить записи?','Все записи этого разговора будут удалены. Настройки памяти сохранятся.',()=>data.messages=[]);break;case'tinyStep':data.tasks.push({id:uid(),title:`Маленький шаг: ${dirName(selectedDirection)}`,direction:selectedDirection,bucket:'soon',date:today(),done:false});save();toast('Маленький шаг ждёт в «Сегодня»');break;case'rest':motivation='Сегодня можно отдохнуть. Твои цели никуда не исчезнут за одну паузу.';render();break;case'analyzeFood':analyzeFoodWithAI();break;case'removeMeal':data.meals=(data.meals||[]).filter(m=>m.id!==id);foodResult='';save();render();break;case'export':exportData();break;case'reset':confirmAction('Удалить все данные?','Дела, привычки, фотографии, память и разговоры будут удалены из этого браузера. Сначала можно скачать копию в настройках.',()=>{localStorage.removeItem(KEY);data={version:1,entered:false,profile:{name:'',story:'',goal:'',style:'gentle',memory:'',useMemory:false,dopamine:false},directions:[],tasks:[],habits:[],inspiration:[],messages:[],meals:[],ideas:[],milestones:[]};unsavedSettings=false;page='today'});break}});
document.addEventListener('submit',e=>{if(e.target.id==='settingsForm'){e.preventDefault();if(persistSettings(new FormData(e.target)))render()}if(e.target.id==='talkForm'){e.preventDefault();appendTalk(new FormData(e.target).get('message'))}if(e.target.id==='foodForm'){e.preventDefault();const val=new FormData(e.target).get('meal')?.trim();if(val){data.meals??=[];data.meals.push({id:uid(),date:today(),text:val});foodResult='';save();render();toast('Записано без оценки')}}if(e.target.id==='motivateForm'){e.preventDefault();const f=new FormData(e.target);selectedDirection=f.get('direction');const d=data.directions.find(d=>d.id===selectedDirection);const name=data.profile.name?`${data.profile.name}, `:'';if(f.get('feeling')==='tired')motivation=`${name}если сил мало, пауза — тоже забота о себе. Можно выбрать отдых, а к «${d.name}» вернуться позже. Тебе не нужно заслуживать передышку.`;else{const intro=({gentle:`${name}давай сделаем это бережно.`,friend:`${name}давай вместе найдём, с чего начать.`,playful:`${name}пять минут побудем великими. А потом решим, продолжать ли.`,cheeky:`${name}ну что, устроим задаче маленький ответный ход?`,direct:`${name}выбери одно простое действие. Этого достаточно для начала.`}[data.profile.style]||`${name}давай начнём с малого.`);motivation=intro+(d.why?`\n\nВот твой собственный ответ «зачем»: ${d.why}`:'\n\nТебе не нужно хотеть сделать всё. Достаточно попробовать один маленький шаг.')+(data.profile.goal?`\n\nТвоя цель: ${data.profile.goal}`:'')+`\n\n${f.get('feeling')==='overwhelmed'?'Уменьшим задачу до первого движения. ':''}Открой нужную страницу или подготовь место. После этого можно остановиться.`;if(data.profile.useMemory&&data.profile.memory)motivation+=`\n\nНапоминание от тебя: ${data.profile.memory}`;}const localMotivation=motivation;if(typeof fetch==='function'){motivation='Секунду, подбираю слова для тебя…';render();aiRequest('motivate',{text:`Мне трудно приступить к направлению «${d?.name||'дело'}». Состояние: ${f.get('feeling')}.`,profile:aiProfile(),reason:d?.why||''}).then(answer=>{motivation=answer;render()}).catch(()=>{motivation=localMotivation;render();toast('ИИ сейчас недоступен. Показан локальный ответ.')})}else render()}});
document.addEventListener('change',e=>{if(e.target.id==='photoInput')addPhoto(e.target.files[0]);if(e.target.id==='styleSelect')$('#stylePreview').textContent=STYLE_PREVIEWS[e.target.value]||STYLE_PREVIEWS.gentle});
window.addEventListener('beforeunload',e=>{if(unsavedSettings){e.preventDefault();e.returnValue=''}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog()});
